import { spawn, execFileSync } from 'node:child_process';
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { once } from 'node:events';
import { mkdir, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { resolve, join } from 'node:path';
import { generateSummary } from './vigolium-summary.mjs';

// Runtime artifacts are generated by server:build, after the static CI checks.
const runtimeRoot = new URL('../server/dist/', import.meta.url);
const { parseConfig } = await import(new URL('config.js', runtimeRoot));
const { openDatabase } = await import(new URL('db.js', runtimeRoot));
const { createRuntimeServer } = await import(new URL('http.js', runtimeRoot));
const { createRealAccount } = await import(new URL('auth/index.js', runtimeRoot));

const outputDir = resolve('vigolium-result/automatic');
const dataDir = await mkdtemp(join(tmpdir(), 'rewind-vigolium-'));
const cli = resolve('node_modules/@vigolium/vigolium/bin/vigolium.js');
const coverage = JSON.parse(
  await readFile(new URL('../security/vigolium-coverage.json', import.meta.url), 'utf8'),
);
assert.equal(coverage.schemaVersion, 1);
assert.ok(
  coverage.contexts.every((context) =>
    context.requests.every((request) => request.method === 'GET'),
  ),
  'Passive fixtures currently support GET requests only',
);
let database;
let server;

async function run(args) {
  const child = spawn(process.execPath, [cli, ...args], { stdio: 'inherit' });
  const timer = setTimeout(() => child.kill(), 360_000);
  try {
    const [code] = await once(child, 'exit');
    if (code !== 0) throw new Error(`Vigolium exited with code ${code}`);
  } finally {
    clearTimeout(timer);
  }
}

try {
  await mkdir(outputDir, { recursive: true });
  const config = parseConfig({
    REWIND_DATA_DIR: dataDir,
    REWIND_HOST: '127.0.0.1',
    REWIND_PORT: '0',
    REWIND_ALLOW_INSECURE_LOCAL_AUTH: 'true',
  });
  database = openDatabase(config, { seedNow: new Date('2026-09-01T00:00:00Z') });
  server = createRuntimeServer(config, database);
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  const origin = `http://127.0.0.1:${server.address().port}`;
  const targets = coverage.contexts
    .find((context) => context.file === 'report')
    .requests.map((request) => request.path);
  const scanFlags = [
    'scan',
    '--passive-only',
    '--only',
    'dynamic-assessment',
    '--skip-heuristics',
    '--scope-origin',
    'strict',
    '--redirect-mode',
    'off',
    '--rate-limit',
    '5',
    '--scanning-max-duration',
    '5m',
  ];
  const credentials = [];
  const accountIds = new Map();
  async function request(path, token, body, expectedStatus = 200) {
    const response = await fetch(`${origin}${path}`, {
      method: body ? 'POST' : 'GET',
      headers: {
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
        ...(body ? { 'Content-Type': 'application/json' } : {}),
      },
      ...(body ? { body: JSON.stringify(body) } : {}),
    });
    assert.equal(response.status, expectedStatus, `Unexpected status for ${path}`);
    return response.json();
  }
  async function provision(username) {
    const password = randomUUID();
    const account = await createRealAccount(database, username, username, password);
    assert.equal(account.ok, true, 'Disposable account creation failed');
    accountIds.set(username, account.account.id);
    const auth = await request('/auth/login', null, { username, password, clientType: 'native' });
    assert.equal(typeof auth.token, 'string');
    credentials.push(password, auth.token);
    return auth.token;
  }
  async function scan(paths, token, label) {
    const flags = ['--db', join(dataDir, `${label}.sqlite`), '--skip-dependency-check'];
    await run([
      ...scanFlags,
      ...flags,
      ...(token ? ['-H', `Authorization: Bearer ${token}`] : []),
      ...paths.flatMap((path) => ['-t', `${origin}${path}`]),
    ]);
    await run([
      'export',
      ...flags,
      '--format',
      'html,jsonl',
      '--omit-response',
      '-o',
      join(dataDir, label),
    ]);
    for (const extension of ['html', 'jsonl']) {
      let content = await readFile(join(dataDir, `${label}.${extension}`), 'utf8');
      for (const credential of credentials) content = content.replaceAll(credential, '[REDACTED]');
      await writeFile(join(outputDir, `${label}.${extension}`), content);
    }
  }
  const owner = await provision('scan-owner');
  const member = await provision('scan-member');
  const outsider = await provision('scan-outsider');
  const created = await request(
    '/real/groups',
    owner,
    {
      name: 'Disposable scan group',
      prompt: 'Security setup trial',
      maxMembers: 4,
    },
    201,
  );
  const groupId = database
    .prepare('SELECT group_id AS groupId FROM real_account_group_selections WHERE account_id = ?')
    .get(accountIds.get('scan-owner')).groupId;
  assert.equal(created.group.id, groupId);
  const groupPath = `/real/groups/${groupId}`;
  const invitation = await request(`${groupPath}/invites`, owner, {}, 201);
  credentials.push(invitation.invite.code);
  await request('/real/invites/accept', member, { code: invitation.invite.code });
  const chatPath = `/realtime/groups/${groupId}/messages`;
  await request(chatPath, owner, { body: 'Disposable scan message' }, 201);
  const contexts = coverage.contexts.map((context) => ({
    ...context,
    requests: context.requests.map((entry) => ({
      ...entry,
      path: entry.path.replaceAll('{groupId}', groupId),
    })),
  }));
  const tokens = { report: null, owner, member, outsider };
  for (const context of contexts) {
    assert.ok(Object.hasOwn(tokens, context.file), 'Unknown fixture identity in coverage manifest');
    for (const entry of context.requests)
      await request(entry.path, tokens[context.file], null, entry.expectedStatus);
    await scan(
      context.requests.map((entry) => entry.path),
      tokens[context.file],
      context.file,
    );
  }
  await request(chatPath, null, null, 401);
  const ownerTargets = contexts
    .find((context) => context.file === 'owner')
    .requests.map((entry) => entry.path);
  const outsiderTargets = contexts
    .find((context) => context.file === 'outsider')
    .requests.map((entry) => entry.path);
  const memberTargets = contexts
    .find((context) => context.file === 'member')
    .requests.map((entry) => entry.path);
  const expectedStatuses = Object.fromEntries(
    contexts.map((context) => [
      context.file,
      Object.fromEntries(context.requests.map((entry) => [entry.path, entry.expectedStatus])),
    ]),
  );
  await writeFile(
    join(outputDir, 'scope.json'),
    JSON.stringify(
      {
        mode: 'passive HTTP',
        sourceCommit:
          process.env.GITHUB_SHA ||
          process.env.REWIND_SCAN_COMMIT ||
          execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(),
        targets,
        ownerTargets,
        memberTargets,
        outsiderTargets,
        contexts: contexts.map(({ file, identity }) => ({ file, identity })),
        expectedStatuses,
        accessChecks: {
          ownerRoutes: '200',
          outsiderGroupAndMembers: '404',
          memberRoutes: '200',
          outsiderChat: '403',
          anonymousChat: '401',
          anonymousSession: '401',
        },
        completedAt: new Date().toISOString(),
        limitations:
          'Passive HTTP with owner, joined member and outsider accounts, group and chat requests. Active checks run separately. No source audit, media journeys or browser crawling. Local HTTP auth is enabled only in this disposable loopback runtime.',
      },
      null,
      2,
    ) + '\n',
  );
  await generateSummary(outputDir);
  console.log(`Vigolium reports: ${outputDir}`);
} finally {
  if (server?.listening) {
    const closed = once(server, 'close');
    server.close();
    server.closeAllConnections();
    await closed;
  }
  database?.close();
  await rm(dataDir, { recursive: true, force: true });
}
